INSERT INTO `cur_candidatos` (`id_extracao`, `rodada`, `titulo_proposto`, `titulo_original`, `ano_original`, `ano_validado`, `periodo_historico`, `categoria`, `pagina_livro`, `pagina_pdf`, `situacao_identificacao`, `status_avaliacao`, `estado_revisao_humana`, `homologado`, `analise_historica_json`, `pendencias_json`, `duplicatas_json`, `observacao_metodologica`, `criado_em`) VALUES
('MCD-00543', 39, 'Inauguração do sistema elétrico de Pearl Street em Nova York', 'Sistema combinou geração centralizada com distribuição e consumidores de iluminação.', 1882, NULL, 'Ano do evento por confirmar', 'eletricidade / redes', 319, 332, 'SEGUNDA_EXTRACAO_EVENTO_COM_RESSALVAS', 'PENDENTE_DE_EVIDENCIAS', 'APROVADO', 0, '{\"o_que_aconteceu\": \"Sistema combinou geração centralizada com distribuição e consumidores de iluminação.\", \"transformacao\": \"Demonstrou operação comercial de rede elétrica urbana.\", \"limitacoes_controversias\": \"A data é de fonte externa; não equiparar central elétrica à invenção da lâmpada.\", \"origem_da_nova_extracao\": \"Varredura adicional do livro-base (segunda extração). Fonte identificada por página impressa, sem afirmar primazia mundial.\", \"trecho_localizado_livro\": \"ines into rural areas. Much the same point regarding technological systems is evident in considering the electric lighting industry that also arose in the last quar- ter of the nineteenth century. Such an industry clearly derived from prior work in the new science of electricity. As celebrated in traditional biographies of great\", \"pagina_livro\": 319, \"pagina_pdf\": 332, \"recorte_temporal\": \"ANO DE EVENTO A CONFERIR\", \"validacao\": \"NÃO REVISADO / NÃO HOMOLOGADO\", \"pesquisa_documental_lote6_20261105\": {\"status\": \"CONFERENCIA_DOCUMENTAL_PARCIAL\", \"instituicao\": \"IEEE\", \"titulo_documental\": \"Pearl Street Station: Powering the First Distribution Network\", \"data_proposta\": \"04/09/1882 (operação)\", \"fato_fonte\": \"A estação Pearl Street começou a operar em Nova York em 4 de setembro de 1882 como uma central de distribuição elétrica de Edison.\", \"ressalva\": \"Não foi a primeira iniciativa elétrica do mundo; delimitar o sistema local e seus componentes.\", \"url\": \"https://doi.org/10.1109/MPE.2024.3464568\", \"limite\": \"A fonte sustenta evento e cronologia; nao gera nota, decisao ou homologacao.\"}, \"convencao_pontuacao_minima_20261105\": {\"nota_minima_operacional\": 1, \"regra\": \"Ausencia de evidencias suficientes para nota maior permite pontuacao minima PROVISORIA, nunca certeza de baixo impacto\", \"precisa_auditoria\": true, \"nao_e_homologacao\": true}}', '[\"Verificar se a ocorrência é um marco tecnológico independente e não apenas fase de uma linhagem já cadastrada.\",\"Conferir os IDs de vínculos antes de concluir que se trata de duplicata.\",\"Revisar as propostas numéricas; lacunas não são notas zero nem um.\",\"Difusão: Obter evidência de adoção efetiva e sua distribuição temporal, não apenas notoriedade histórica.\",\"Magnitude: Quantificar alteração causada pela técnica, evitando inferência baseada na fama do inventor.\",\"Alcance: Determinar alcance geográfico ou setorial com documentos, distinguindo curto e longo prazo.\",\"Persistência: Determinar durabilidade da tecnologia específica e das linhagens derivadas.\",\"Pervasividade: Demonstrar dependência tecnológica posterior em áreas distintas.\",\"Aprimoramento: Identificar aperfeiçoamentos derivados especificamente do marco.\"]', '[\"MCD-00315\",\"MCD-00492\"]', 'Livro p.319; dados de extração e 5/11 propostas; não homologar sem revisão.', '2026-11-04 18:43:55'),
('MCD-00544', 39, 'Patente do Benz Patent-Motorwagen', 'Veículo a gasolina articulava motor, chassis e direção num conjunto próprio.', 1886, NULL, 'Ano do evento por confirmar', 'transporte / automóveis', 339, 352, 'SEGUNDA_EXTRACAO_EVENTO_COM_RESSALVAS', 'PENDENTE_DE_EVIDENCIAS', 'APROVADO', 0, '{\"o_que_aconteceu\": \"Veículo a gasolina articulava motor, chassis e direção num conjunto próprio.\", \"transformacao\": \"Demonstração inicial do automóvel de combustão leve.\", \"limitacoes_controversias\": \"Patente de 1886 não implica produção em massa, que ocorreu depois.\", \"origem_da_nova_extracao\": \"Varredura adicional do livro-base (segunda extração). Fonte identificada por página impressa, sem afirmar primazia mundial.\", \"trecho_localizado_livro\": \"n trans- forming the socio-industrial landscape on a global scale. Several para- digmatic industries—the automobile, electrification, aviation, domes- tic technologies, and entertainment—illustrate how the network of technical innovation and its social consequences formed intricate and interlocked systems that spread across the \", \"pagina_livro\": 339, \"pagina_pdf\": 352, \"recorte_temporal\": \"ANO DE EVENTO A CONFERIR\", \"validacao\": \"NÃO REVISADO / NÃO HOMOLOGADO\", \"pesquisa_documental_lote6_20261105\": {\"status\": \"CONFERENCIA_DOCUMENTAL_PARCIAL\", \"instituicao\": \"Mercedes-Benz Group\", \"titulo_documental\": \"Benz Patent Motor Car 1885-1886\", \"data_proposta\": \"29/01/1886 (depósito de patente)\", \"fato_fonte\": \"Carl Benz depositou em 29 de janeiro de 1886 a patente do veículo motorizado que havia concluído em 1885.\", \"ressalva\": \"Separar fabricação em 1885, depósito de patente em 1886 e saída pública do veículo meses depois.\", \"url\": \"https://group.mercedes-benz.com/company/tradition/company-history/1885-1886.html\", \"limite\": \"A fonte sustenta evento e cronologia; nao gera nota, decisao ou homologacao.\"}, \"convencao_pontuacao_minima_20261105\": {\"nota_minima_operacional\": 1, \"regra\": \"Ausencia de evidencias suficientes para nota maior permite pontuacao minima PROVISORIA, nunca certeza de baixo impacto\", \"precisa_auditoria\": true, \"nao_e_homologacao\": true}}', '[\"Verificar se a ocorrência é um marco tecnológico independente e não apenas fase de uma linhagem já cadastrada.\",\"Conferir os IDs de vínculos antes de concluir que se trata de duplicata.\",\"Revisar as propostas numéricas; lacunas não são notas zero nem um.\",\"Difusão: Obter evidência de adoção efetiva e sua distribuição temporal, não apenas notoriedade histórica.\",\"Magnitude: Quantificar alteração causada pela técnica, evitando inferência baseada na fama do inventor.\",\"Alcance: Determinar alcance geográfico ou setorial com documentos, distinguindo curto e longo prazo.\",\"Persistência: Determinar durabilidade da tecnologia específica e das linhagens derivadas.\",\"Pervasividade: Demonstrar dependência tecnológica posterior em áreas distintas.\",\"Aprimoramento: Identificar aperfeiçoamentos derivados especificamente do marco.\",\"Complementaridade: Documentar interfaces e integração com outros sistemas tecnológicos.\"]', '[\"MCD-00306\",\"MCD-00498\"]', 'Livro p.339; dados de extração e 4/11 propostas; não homologar sem revisão.', '2026-11-04 18:43:55'),
('MCD-00545', 39, 'Demonstração do motor Diesel funcional', 'Desenvolvimento de motor de ignição por compressão após experimentos do inventor Rudolf Diesel.', 1897, NULL, 'Ano do evento por confirmar', 'máquinas térmicas / motores', 339, 352, 'SEGUNDA_EXTRACAO_EVENTO_COM_RESSALVAS', 'PENDENTE_DE_EVIDENCIAS', 'APROVADO', 0, '{\"o_que_aconteceu\": \"Desenvolvimento de motor de ignição por compressão após experimentos do inventor Rudolf Diesel.\", \"transformacao\": \"Nova família de motores térmicos para transporte e indústria.\", \"limitacoes_controversias\": \"O livro só contextualiza motores diesel; ano e protótipo devem ser confrontados com documentação adicional.\", \"origem_da_nova_extracao\": \"Varredura adicional do livro-base (segunda extração). Fonte identificada por página impressa, sem afirmar primazia mundial.\", \"trecho_localizado_livro\": \"railroads and steamships—to the end of the nine- teenth century. Then, with the development of effective diesel and gaso- line internal-combustion engines by German engineers a new prime mover appeared that, mated to the wagon and the plow, created the\", \"pagina_livro\": 339, \"pagina_pdf\": 352, \"recorte_temporal\": \"ANO DE EVENTO A CONFERIR\", \"validacao\": \"NÃO REVISADO / NÃO HOMOLOGADO\", \"pesquisa_documental_lote6_20261105\": {\"status\": \"CONFERENCIA_DOCUMENTAL_PARCIAL\", \"instituicao\": \"Deutsches Museum\", \"titulo_documental\": \"Energy and Engines: Diesel Motor\", \"data_proposta\": \"1897 (motor funcional)\", \"fato_fonte\": \"O Deutsches Museum preserva e descreve um motor Diesel experimental de 1897 após o desenvolvimento e as patentes da década de 1890.\", \"ressalva\": \"A data refere-se à demonstração de motor funcional, não a início de comercialização automobilística.\", \"url\": \"https://www.deutsches-museum.de/museum/pressemappe/museumsinsel/ausstellungen/energie-motoren\", \"limite\": \"A fonte sustenta evento e cronologia; nao gera nota, decisao ou homologacao.\"}, \"convencao_pontuacao_minima_20261105\": {\"nota_minima_operacional\": 1, \"regra\": \"Ausencia de evidencias suficientes para nota maior permite pontuacao minima PROVISORIA, nunca certeza de baixo impacto\", \"precisa_auditoria\": true, \"nao_e_homologacao\": true}}', '[\"Verificar se a ocorrência é um marco tecnológico independente e não apenas fase de uma linhagem já cadastrada.\",\"Conferir os IDs de vínculos antes de concluir que se trata de duplicata.\",\"Revisar as propostas numéricas; lacunas não são notas zero nem um.\",\"Falta uma segunda referência externa sobre o evento concreto; o livro-base não basta para aprovação final.\",\"Difusão: Obter evidência de adoção efetiva e sua distribuição temporal, não apenas notoriedade histórica.\",\"Magnitude: Quantificar alteração causada pela técnica, evitando inferência baseada na fama do inventor.\",\"Alcance: Determinar alcance geográfico ou setorial com documentos, distinguindo curto e longo prazo.\",\"Persistência: Determinar durabilidade da tecnologia específica e das linhagens derivadas.\",\"Independência: Confrontar pelo menos duas linhas independentes de evidência sobre o mesmo evento.\",\"Datação: Estabelecer se o ano é o de concepção, construção, patente, difusão ou publicação.\",\"Consistência: Confrontar divergências de datas, atribuições e delimitações.\",\"Pervasividade: Demonstrar dependência tecnológica posterior em áreas distintas.\",\"Aprimoramento: Identificar aperfeiçoamentos derivados especificamente do marco.\",\"Complementaridade: Documentar interfaces e integração com outros sistemas tecnológicos.\"]', '[\"MCD-00306\"]', 'Livro p.339; dados de extração e 1/11 propostas; não homologar sem revisão.', '2026-11-04 18:43:55'),
('MCD-00546', 39, 'Observação da radioatividade de urânio por Becquerel', 'Placas fotográficas revelaram emissões de compostos de urânio.', 1896, NULL, 'Ano do evento por confirmar', 'física / radioatividade', 366, 379, 'SEGUNDA_EXTRACAO_EVENTO_COM_RESSALVAS', 'PENDENTE_DE_EVIDENCIAS', 'APROVADO', 0, '{\"o_que_aconteceu\": \"Placas fotográficas revelaram emissões de compostos de urânio.\", \"transformacao\": \"Forneceu novo fenômeno para pesquisa da matéria e instrumentação radiológica.\", \"limitacoes_controversias\": \"Descoberta física pode não atender sozinha ao escopo tecnológico do índice.\", \"origem_da_nova_extracao\": \"Varredura adicional do livro-base (segunda extração). Fonte identificada por página impressa, sem afirmar primazia mundial.\", \"trecho_localizado_livro\": \"er all. How was that to be squared with received notions? A year earlier, French physicist Antoine-Henri Becquerel (1852– 1908) accidentally noticed that uranium ore clouded unexposed photo- graphic plates, and he thus uncovered still another unexpected natural 366 S C I E N C E A N D I N D U S T R I A L C I V I L I Z AT I O N\", \"pagina_livro\": 366, \"pagina_pdf\": 379, \"recorte_temporal\": \"ANO DE EVENTO A CONFERIR\", \"validacao\": \"NÃO REVISADO / NÃO HOMOLOGADO\", \"pesquisa_documental_lote6_20261105\": {\"status\": \"CONFERENCIA_DOCUMENTAL_PARCIAL\", \"instituicao\": \"Nobel Prize\", \"titulo_documental\": \"Henri Becquerel biographical\", \"data_proposta\": \"1896 (fenômeno de radioatividade natural)\", \"fato_fonte\": \"Becquerel identificou em 1896 a emissão de radiação por sais de urânio sem exposição luminosa direta.\", \"ressalva\": \"Evitar atribuir a Becquerel todos os desenvolvimentos posteriores da física nuclear.\", \"url\": \"https://www.nobelprize.org/prizes/physics/1903/becquerel/biographical/?print=1\", \"limite\": \"A fonte sustenta evento e cronologia; nao gera nota, decisao ou homologacao.\"}, \"convencao_pontuacao_minima_20261105\": {\"nota_minima_operacional\": 1, \"regra\": \"Ausencia de evidencias suficientes para nota maior permite pontuacao minima PROVISORIA, nunca certeza de baixo impacto\", \"precisa_auditoria\": true, \"nao_e_homologacao\": true}}', '[\"Verificar se a ocorrência é um marco tecnológico independente e não apenas fase de uma linhagem já cadastrada.\",\"Conferir os IDs de vínculos antes de concluir que se trata de duplicata.\",\"Revisar as propostas numéricas; lacunas não são notas zero nem um.\",\"Falta uma segunda referência externa sobre o evento concreto; o livro-base não basta para aprovação final.\",\"Difusão: Obter evidência de adoção efetiva e sua distribuição temporal, não apenas notoriedade histórica.\",\"Magnitude: Quantificar alteração causada pela técnica, evitando inferência baseada na fama do inventor.\",\"Alcance: Determinar alcance geográfico ou setorial com documentos, distinguindo curto e longo prazo.\",\"Persistência: Determinar durabilidade da tecnologia específica e das linhagens derivadas.\",\"Independência: Confrontar pelo menos duas linhas independentes de evidência sobre o mesmo evento.\",\"Datação: Estabelecer se o ano é o de concepção, construção, patente, difusão ou publicação.\",\"Consistência: Confrontar divergências de datas, atribuições e delimitações.\",\"Pervasividade: Demonstrar dependência tecnológica posterior em áreas distintas.\",\"Aprimoramento: Identificar aperfeiçoamentos derivados especificamente do marco.\",\"Complementaridade: Documentar interfaces e integração com outros sistemas tecnológicos.\"]', '[\"MCD-00355\"]', 'Livro p.366; dados de extração e 1/11 propostas; não homologar sem revisão.', '2026-11-04 18:43:55'),
('MCD-00547', 39, 'Descoberta e investigação do rádio pelo casal Curie', 'Pesquisas de radioatividade levaram à identificação de novos materiais radioativos.', 1898, NULL, 'Ano do evento por confirmar', 'química / radioatividade', 367, 380, 'SEGUNDA_EXTRACAO_EVENTO_COM_RESSALVAS', 'PENDENTE_DE_EVIDENCIAS', 'APROVADO', 0, '{\"o_que_aconteceu\": \"Pesquisas de radioatividade levaram à identificação de novos materiais radioativos.\", \"transformacao\": \"Impactou química e instrumentação física posterior.\", \"limitacoes_controversias\": \"Trabalhos de 1898 envolvem polônio e rádio; distinguir descobertas e atribuições.\", \"origem_da_nova_extracao\": \"Varredura adicional do livro-base (segunda extração). Fonte identificada por página impressa, sem afirmar primazia mundial.\", \"trecho_localizado_livro\": \"ioactivity and the second in chemistry in 1911 on her own for her discovery of the radioactive ele- ment radium. After her seminal work it became clear that certain heavy elements spontaneously emitted several different sorts of radiation, in- cluding electrons, superenergetic electromagnetic waves (gamma rays), and subatomic pa\", \"pagina_livro\": 367, \"pagina_pdf\": 380, \"recorte_temporal\": \"ANO DE EVENTO A CONFERIR\", \"validacao\": \"NÃO REVISADO / NÃO HOMOLOGADO\", \"pesquisa_documental_lote6_20261105\": {\"status\": \"CONFERENCIA_DOCUMENTAL_PARCIAL\", \"instituicao\": \"Nobel Prize\", \"titulo_documental\": \"Marie and Pierre Curie discovery of polonium and radium\", \"data_proposta\": \"1898 (anúncio de novos elementos)\", \"fato_fonte\": \"Marie e Pierre Curie comunicaram em 1898 resultados para polônio e rádio, consolidando pesquisa sobre materiais radioativos.\", \"ressalva\": \"Anúncio em 1898 não equivale ao isolamento do rádio puro, que ocorreu posteriormente.\", \"url\": \"https://www.nobelprize.org/prizes/lists/marie-and-pierre-curie-and-the-discovery-of-polonium-and-radium/\", \"limite\": \"A fonte sustenta evento e cronologia; nao gera nota, decisao ou homologacao.\"}, \"convencao_pontuacao_minima_20261105\": {\"nota_minima_operacional\": 1, \"regra\": \"Ausencia de evidencias suficientes para nota maior permite pontuacao minima PROVISORIA, nunca certeza de baixo impacto\", \"precisa_auditoria\": true, \"nao_e_homologacao\": true}}', '[\"Verificar se a ocorrência é um marco tecnológico independente e não apenas fase de uma linhagem já cadastrada.\",\"Conferir os IDs de vínculos antes de concluir que se trata de duplicata.\",\"Revisar as propostas numéricas; lacunas não são notas zero nem um.\",\"Falta uma segunda referência externa sobre o evento concreto; o livro-base não basta para aprovação final.\",\"Difusão: Obter evidência de adoção efetiva e sua distribuição temporal, não apenas notoriedade histórica.\",\"Magnitude: Quantificar alteração causada pela técnica, evitando inferência baseada na fama do inventor.\",\"Alcance: Determinar alcance geográfico ou setorial com documentos, distinguindo curto e longo prazo.\",\"Persistência: Determinar durabilidade da tecnologia específica e das linhagens derivadas.\",\"Independência: Confrontar pelo menos duas linhas independentes de evidência sobre o mesmo evento.\",\"Datação: Estabelecer se o ano é o de concepção, construção, patente, difusão ou publicação.\",\"Consistência: Confrontar divergências de datas, atribuições e delimitações.\",\"Pervasividade: Demonstrar dependência tecnológica posterior em áreas distintas.\",\"Aprimoramento: Identificar aperfeiçoamentos derivados especificamente do marco.\",\"Complementaridade: Documentar interfaces e integração com outros sistemas tecnológicos.\"]', '[\"MCD-00359\"]', 'Livro p.367; dados de extração e 1/11 propostas; não homologar sem revisão.', '2026-11-04 18:43:55'),
('MCD-00548', 40, 'Desenvolvimento da válvula triodo Audion por Lee de Forest', 'Dispositivo de três eletrodos permitiu amplificar sinais de radiofrequência.', 1906, NULL, 'Ano do evento por confirmar', 'eletrônica / válvulas', 353, 366, 'SEGUNDA_EXTRACAO_EVENTO_COM_RESSALVAS', 'PENDENTE_DE_EVIDENCIAS', 'APROVADO', 0, '{\"o_que_aconteceu\": \"Dispositivo de três eletrodos permitiu amplificar sinais de radiofrequência.\", \"transformacao\": \"Contribuiu para telefonia e rádio eletrônicos antes do transistor.\", \"limitacoes_controversias\": \"Há diferenças entre protótipo de 1906 e patente de 1907; fonte documental identifica ambas.\", \"origem_da_nova_extracao\": \"Varredura adicional do livro-base (segunda extração). Fonte identificada por página impressa, sem afirmar primazia mundial.\", \"trecho_localizado_livro\": \" of inventors and radio ama- teurs in the early 1900s, improvements marked, notably, by the ampli- fying Audion vacuum tube patented by Lee De Forest in 1906. In the fall of 1920 regular commercial radio broadcasts began over a 100- watt station in Pittsburgh, KDKA; by 1922, 564 licensed stations dot- ted the country. Radio netw\", \"pagina_livro\": 353, \"pagina_pdf\": 366, \"recorte_temporal\": \"ANO DE EVENTO A CONFERIR\", \"validacao\": \"NÃO REVISADO / NÃO HOMOLOGADO\", \"pesquisa_documental_lote4_20261105\": {\"status\": \"CONFERENCIA_DOCUMENTAL_PARCIAL\", \"data_documentada\": \"1906–1907\", \"instituicao\": \"Smithsonian National Museum of American History\", \"documento\": \"Audion vacuum tube\", \"fato_comprovado\": \"O Smithsonian registra o desenvolvimento da válvula Audion por Lee de Forest em 1906 e o contexto de patente em 1907.\", \"ressalva_ou_pendencia\": \"Distinguir demonstração, patente e aperfeiçoamentos que permitiram ganho de amplificação confiável.\", \"url\": \"https://americanhistory.si.edu/collections/object/nmah_1289117\", \"limite\": \"Pesquisa de evento e data. Não valida automaticamente impacto ou as 11 notas.\"}, \"convencao_pontuacao_minima_20261105\": {\"nota_minima_operacional\": 1, \"regra\": \"Ausencia de evidencias suficientes para nota maior permite pontuacao minima PROVISORIA, nunca certeza de baixo impacto\", \"precisa_auditoria\": true, \"nao_e_homologacao\": true}}', '[\"Verificar se a ocorrência é um marco tecnológico independente e não apenas fase de uma linhagem já cadastrada.\",\"Conferir os IDs de vínculos antes de concluir que se trata de duplicata.\",\"Revisar as propostas numéricas; lacunas não são notas zero nem um.\",\"Difusão: Obter evidência de adoção efetiva e sua distribuição temporal, não apenas notoriedade histórica.\",\"Magnitude: Quantificar alteração causada pela técnica, evitando inferência baseada na fama do inventor.\",\"Alcance: Determinar alcance geográfico ou setorial com documentos, distinguindo curto e longo prazo.\",\"Persistência: Determinar durabilidade da tecnologia específica e das linhagens derivadas.\",\"Datação: Estabelecer se o ano é o de concepção, construção, patente, difusão ou publicação.\",\"Pervasividade: Demonstrar dependência tecnológica posterior em áreas distintas.\",\"Aprimoramento: Identificar aperfeiçoamentos derivados especificamente do marco.\",\"Complementaridade: Documentar interfaces e integração com outros sistemas tecnológicos.\"]', '[\"MCD-00327\"]', 'Livro p.353; dados de extração e 3/11 propostas; não homologar sem revisão.', '2026-11-04 18:43:55'),
('MCD-00549', 40, 'Modelo nuclear do átomo apresentado por Rutherford', 'Interpretação experimental de espalhamento de partículas e estrutura atômica.', 1911, NULL, 'Ano do evento por confirmar', 'física / modelo atômico', 370, 383, 'SEGUNDA_EXTRACAO_EVENTO_COM_RESSALVAS', 'PENDENTE_DE_EVIDENCIAS', 'APROVADO', 0, '{\"o_que_aconteceu\": \"Interpretação experimental de espalhamento de partículas e estrutura atômica.\", \"transformacao\": \"Alterou fundamentos teóricos de pesquisas que depois sustentaram tecnologias nucleares.\", \"limitacoes_controversias\": \"Descoberta científica com efeitos indiretos; conferir elegibilidade tecnológica.\", \"origem_da_nova_extracao\": \"Varredura adicional do livro-base (segunda extração). Fonte identificada por página impressa, sem afirmar primazia mundial.\", \"trecho_localizado_livro\": \" Using radioactive emissions as a tool to investigate the interior structure of the atom, in 1911 Ernest Rutherford (1871–1937) announced that atoms were composed mostly of empty space. Along with the Danish physicist Niels Bohr (1885– 1962), Rutherford proposed a model for the atom that had electrons orbiting a solid nucleus, m\", \"pagina_livro\": 370, \"pagina_pdf\": 383, \"recorte_temporal\": \"ANO DE EVENTO A CONFERIR\", \"validacao\": \"NÃO REVISADO / NÃO HOMOLOGADO\", \"pesquisa_documental_lote4_20261105\": {\"status\": \"CONFERENCIA_DOCUMENTAL_PARCIAL\", \"data_documentada\": \"1911\", \"instituicao\": \"University of Manchester\", \"documento\": \"Physics history and heritage — Rutherford\", \"fato_comprovado\": \"A University of Manchester situa a formulação do modelo nuclear do átomo por Ernest Rutherford em 1911.\", \"ressalva_ou_pendencia\": \"Não confundir experimento de espalhamento de 1909 com publicação/interpretação do modelo em 1911.\", \"url\": \"https://www.physics.manchester.ac.uk/about/history-and-heritage/\", \"limite\": \"Pesquisa de evento e data. Não valida automaticamente impacto ou as 11 notas.\"}, \"convencao_pontuacao_minima_20261105\": {\"nota_minima_operacional\": 1, \"regra\": \"Ausencia de evidencias suficientes para nota maior permite pontuacao minima PROVISORIA, nunca certeza de baixo impacto\", \"precisa_auditoria\": true, \"nao_e_homologacao\": true}}', '[\"Verificar se a ocorrência é um marco tecnológico independente e não apenas fase de uma linhagem já cadastrada.\",\"Conferir os IDs de vínculos antes de concluir que se trata de duplicata.\",\"Revisar as propostas numéricas; lacunas não são notas zero nem um.\",\"Falta uma segunda referência externa sobre o evento concreto; o livro-base não basta para aprovação final.\",\"Difusão: Obter evidência de adoção efetiva e sua distribuição temporal, não apenas notoriedade histórica.\",\"Magnitude: Quantificar alteração causada pela técnica, evitando inferência baseada na fama do inventor.\",\"Alcance: Determinar alcance geográfico ou setorial com documentos, distinguindo curto e longo prazo.\",\"Persistência: Determinar durabilidade da tecnologia específica e das linhagens derivadas.\",\"Independência: Confrontar pelo menos duas linhas independentes de evidência sobre o mesmo evento.\",\"Consistência: Confrontar divergências de datas, atribuições e delimitações.\",\"Pervasividade: Demonstrar dependência tecnológica posterior em áreas distintas.\",\"Aprimoramento: Identificar aperfeiçoamentos derivados especificamente do marco.\",\"Complementaridade: Documentar interfaces e integração com outros sistemas tecnológicos.\"]', '[\"MCD-00362\"]', 'Livro p.370; dados de extração e 2/11 propostas; não homologar sem revisão.', '2026-11-04 18:43:55'),
('MCD-00550', 40, 'Início de transmissões regulares pela emissora KDKA', 'Estação de Pittsburgh realizou transmissões comerciais de rádio.', 1920, NULL, 'Ano do evento por confirmar', 'radiodifusão / serviços', 353, 366, 'SEGUNDA_EXTRACAO_EVENTO_COM_RESSALVAS', 'PENDENTE_DE_EVIDENCIAS', 'APROVADO', 0, '{\"o_que_aconteceu\": \"Estação de Pittsburgh realizou transmissões comerciais de rádio.\", \"transformacao\": \"Marcou uma etapa na passagem da telegrafia sem fio para radiodifusão de massa.\", \"limitacoes_controversias\": \"Não é invenção do rádio ou da primeira transmissão de voz.\", \"origem_da_nova_extracao\": \"Varredura adicional do livro-base (segunda extração). Fonte identificada por página impressa, sem afirmar primazia mundial.\", \"trecho_localizado_livro\": \"6. In the fall of 1920 regular commercial radio broadcasts began over a 100- watt station in Pittsburgh, KDKA; by 1922, 564 licensed stations dot- ted the country. Radio networks emerged with the BBC in 1922 and NBC in 1926. Radio quickly became a new and pleasant form of home entertainment, and the radio receiver an early piece\", \"pagina_livro\": 353, \"pagina_pdf\": 366, \"recorte_temporal\": \"ANO DE EVENTO A CONFERIR\", \"validacao\": \"NÃO REVISADO / NÃO HOMOLOGADO\", \"pesquisa_documental_lote4_20261105\": {\"status\": \"CONFERENCIA_DOCUMENTAL_PARCIAL\", \"data_documentada\": \"02/11/1920\", \"instituicao\": \"Federal Judicial Center (USA)\", \"documento\": \"Early radio in federal courts\", \"fato_comprovado\": \"A história da radiodifusão nos EUA documenta a transmissão ligada à KDKA de resultados eleitorais em novembro de 1920.\", \"ressalva_ou_pendencia\": \"A prioridade como primeira emissora comercial é contestada; verificar identificação 8ZZ/KDKA e critério de regularidade.\", \"url\": \"https://www.fjc.gov/history/spotlight-judicial-history/early-radio-in-federal-courts\", \"limite\": \"Pesquisa de evento e data. Não valida automaticamente impacto ou as 11 notas.\"}, \"convencao_pontuacao_minima_20261105\": {\"nota_minima_operacional\": 1, \"regra\": \"Ausencia de evidencias suficientes para nota maior permite pontuacao minima PROVISORIA, nunca certeza de baixo impacto\", \"precisa_auditoria\": true, \"nao_e_homologacao\": true}}', '[\"Verificar se a ocorrência é um marco tecnológico independente e não apenas fase de uma linhagem já cadastrada.\",\"Conferir os IDs de vínculos antes de concluir que se trata de duplicata.\",\"Revisar as propostas numéricas; lacunas não são notas zero nem um.\",\"Falta uma segunda referência externa sobre o evento concreto; o livro-base não basta para aprovação final.\",\"Difusão: Obter evidência de adoção efetiva e sua distribuição temporal, não apenas notoriedade histórica.\",\"Magnitude: Quantificar alteração causada pela técnica, evitando inferência baseada na fama do inventor.\",\"Alcance: Determinar alcance geográfico ou setorial com documentos, distinguindo curto e longo prazo.\",\"Persistência: Determinar durabilidade da tecnologia específica e das linhagens derivadas.\",\"Independência: Confrontar pelo menos duas linhas independentes de evidência sobre o mesmo evento.\",\"Consistência: Confrontar divergências de datas, atribuições e delimitações.\",\"Pervasividade: Demonstrar dependência tecnológica posterior em áreas distintas.\",\"Aprimoramento: Identificar aperfeiçoamentos derivados especificamente do marco.\",\"Complementaridade: Documentar interfaces e integração com outros sistemas tecnológicos.\"]', '[\"MCD-00329\"]', 'Livro p.353; dados de extração e 2/11 propostas; não homologar sem revisão.', '2026-11-04 18:43:55'),
('MCD-00551', 40, 'Primeira reação nuclear controlada na Chicago Pile-1', 'Equipe de Enrico Fermi tornou uma reação em cadeia sustentada sob controle experimental.', 1942, NULL, 'Ano do evento por confirmar', 'engenharia nuclear / reatores', 394, 407, 'SEGUNDA_EXTRACAO_EVENTO_COM_RESSALVAS', 'PENDENTE_DE_EVIDENCIAS', 'APROVADO', 0, '{\"o_que_aconteceu\": \"Equipe de Enrico Fermi tornou uma reação em cadeia sustentada sob controle experimental.\", \"transformacao\": \"Validou operacionalmente o princípio dos reatores nucleares.\", \"limitacoes_controversias\": \"Diferente da descoberta de fissão em 1938 e da explosão nuclear de 1945.\", \"origem_da_nova_extracao\": \"Varredura adicional do livro-base (segunda extração). Fonte identificada por página impressa, sem afirmar primazia mundial.\", \"trecho_localizado_livro\": \"mber 1942 beneath a foot- ball stadium at the University of Chicago, the Italian émigré scientist Enrico Fermi succeeded in creating the first controlled nuclear chain reaction. On July 16, 1945, the team directed by American physicist J. Robert Oppenheimer set off the world’s first atomic explosion at the Trinity site near the \", \"pagina_livro\": 394, \"pagina_pdf\": 407, \"recorte_temporal\": \"ANO DE EVENTO A CONFERIR\", \"validacao\": \"NÃO REVISADO / NÃO HOMOLOGADO\", \"pesquisa_documental_lote4_20261105\": {\"status\": \"CONFERENCIA_DOCUMENTAL_PARCIAL\", \"data_documentada\": \"02/12/1942\", \"instituicao\": \"US Department of Energy\", \"documento\": \"The First Reactor\", \"fato_comprovado\": \"O DOE documenta a reação nuclear em cadeia autossustentada e controlada obtida no reator Chicago Pile-1 em 2 de dezembro de 1942.\", \"ressalva_ou_pendencia\": \"Trata-se de reação controlada em laboratório, não de produção de eletricidade comercial.\", \"url\": \"https://www.energy.gov/ne/articles/first-reactor\", \"limite\": \"Pesquisa de evento e data. Não valida automaticamente impacto ou as 11 notas.\"}, \"convencao_pontuacao_minima_20261105\": {\"nota_minima_operacional\": 1, \"regra\": \"Ausencia de evidencias suficientes para nota maior permite pontuacao minima PROVISORIA, nunca certeza de baixo impacto\", \"precisa_auditoria\": true, \"nao_e_homologacao\": true}}', '[\"Verificar se a ocorrência é um marco tecnológico independente e não apenas fase de uma linhagem já cadastrada.\",\"Conferir os IDs de vínculos antes de concluir que se trata de duplicata.\",\"Revisar as propostas numéricas; lacunas não são notas zero nem um.\",\"Difusão: Obter evidência de adoção efetiva e sua distribuição temporal, não apenas notoriedade histórica.\",\"Magnitude: Quantificar alteração causada pela técnica, evitando inferência baseada na fama do inventor.\",\"Alcance: Determinar alcance geográfico ou setorial com documentos, distinguindo curto e longo prazo.\",\"Persistência: Determinar durabilidade da tecnologia específica e das linhagens derivadas.\",\"Pervasividade: Demonstrar dependência tecnológica posterior em áreas distintas.\",\"Aprimoramento: Identificar aperfeiçoamentos derivados especificamente do marco.\",\"Complementaridade: Documentar interfaces e integração com outros sistemas tecnológicos.\"]', '[\"MCD-00400\"]', 'Livro p.394; dados de extração e 4/11 propostas; não homologar sem revisão.', '2026-11-04 18:43:55'),
('MCD-00552', 40, 'Introdução da vacina de Jonas Salk contra a poliomielite', 'Vacina inativada foi introduzida nos Estados Unidos para prevenção da poliomielite.', 1955, NULL, 'Ano do evento por confirmar', 'medicina / vacinas', 400, 413, 'SEGUNDA_EXTRACAO_EVENTO_COM_RESSALVAS', 'PENDENTE_DE_EVIDENCIAS', 'APROVADO', 0, '{\"o_que_aconteceu\": \"Vacina inativada foi introduzida nos Estados Unidos para prevenção da poliomielite.\", \"transformacao\": \"Apoiou campanhas posteriores de prevenção de doença infecciosa.\", \"limitacoes_controversias\": \"É necessário registrar também limitações de qualidade e o incidente Cutter de 1955.\", \"origem_da_nova_extracao\": \"Varredura adicional do livro-base (segunda extração). Fonte identificada por página impressa, sem afirmar primazia mundial.\", \"trecho_localizado_livro\": \"icial effect on mortality rates and improved public health. The vaccines developed in the 1950s by Jonas Salk and A. B. Sabin against poliomyelitis created tremendous public health benefits and attention. Techniques surrounding in vitro fertilization exemplify high-tech medical science and practice today. Human in vitro fertiliz\", \"pagina_livro\": 400, \"pagina_pdf\": 413, \"recorte_temporal\": \"ANO DE EVENTO A CONFERIR\", \"validacao\": \"NÃO REVISADO / NÃO HOMOLOGADO\", \"pesquisa_documental_lote4_20261105\": {\"status\": \"CONFERENCIA_DOCUMENTAL_PARCIAL\", \"data_documentada\": \"1955\", \"instituicao\": \"CDC\", \"documento\": \"Pink Book — Poliomyelitis\", \"fato_comprovado\": \"O CDC registra a licença e ampla adoção inicial de vacinas contra poliomielite nos EUA em 1955.\", \"ressalva_ou_pendencia\": \"A introdução da vacina Salk não foi a eliminação imediata da poliomielite; reconhecer incidente Cutter em 1955.\", \"url\": \"https://www.cdc.gov/pinkbook/hcp/table-of-contents/chapter-18-poliomyelitis.html\", \"limite\": \"Pesquisa de evento e data. Não valida automaticamente impacto ou as 11 notas.\"}, \"convencao_pontuacao_minima_20261105\": {\"nota_minima_operacional\": 1, \"regra\": \"Ausencia de evidencias suficientes para nota maior permite pontuacao minima PROVISORIA, nunca certeza de baixo impacto\", \"precisa_auditoria\": true, \"nao_e_homologacao\": true}}', '[\"Verificar se a ocorrência é um marco tecnológico independente e não apenas fase de uma linhagem já cadastrada.\",\"Conferir os IDs de vínculos antes de concluir que se trata de duplicata.\",\"Revisar as propostas numéricas; lacunas não são notas zero nem um.\",\"Difusão: Obter evidência de adoção efetiva e sua distribuição temporal, não apenas notoriedade histórica.\",\"Magnitude: Quantificar alteração causada pela técnica, evitando inferência baseada na fama do inventor.\",\"Alcance: Determinar alcance geográfico ou setorial com documentos, distinguindo curto e longo prazo.\",\"Persistência: Determinar durabilidade da tecnologia específica e das linhagens derivadas.\",\"Pervasividade: Demonstrar dependência tecnológica posterior em áreas distintas.\",\"Aprimoramento: Identificar aperfeiçoamentos derivados especificamente do marco.\",\"Complementaridade: Documentar interfaces e integração com outros sistemas tecnológicos.\"]', '[\"MCD-00411\"]', 'Livro p.400; dados de extração e 4/11 propostas; não homologar sem revisão.', '2026-11-04 18:43:55'),
('MCD-00553', 40, 'Demonstração do primeiro laser funcional por Theodore Maiman', 'Emissão óptica estimulada coerente produzida experimentalmente em laser de rubi.', 1960, NULL, 'Ano do evento por confirmar', 'óptica / lasers', 412, 425, 'SEGUNDA_EXTRACAO_EVENTO_COM_RESSALVAS', 'PENDENTE_DE_EVIDENCIAS', 'APROVADO', 0, '{\"o_que_aconteceu\": \"Emissão óptica estimulada coerente produzida experimentalmente em laser de rubi.\", \"transformacao\": \"Permitiu nova família de instrumentos ópticos e aplicações tecnológicas.\", \"limitacoes_controversias\": \"McClellan e Dorn atribuem laser a Gould em 1957; a fonte especializada distingue conceito de equipamento funcional em 1960.\", \"origem_da_nova_extracao\": \"Varredura adicional do livro-base (segunda extração). Fonte identificada por página impressa, sem afirmar primazia mundial.\", \"trecho_localizado_livro\": \"between pure scientific research and the separate application of knowledge. By contrast, the case of the laser, invented by Gordon Gould in 1957, blurs the distinction between discovery and application, in that the under- lying physics and the practical tool emerged simultaneously—“in a flash,” as Gould put it. The fact that Gou\", \"pagina_livro\": 412, \"pagina_pdf\": 425, \"recorte_temporal\": \"ANO DE EVENTO A CONFERIR\", \"validacao\": \"NÃO REVISADO / NÃO HOMOLOGADO\", \"pesquisa_documental_lote4_20261105\": {\"status\": \"CONFERENCIA_DOCUMENTAL_PARCIAL\", \"data_documentada\": \"mai/1960\", \"instituicao\": \"Smithsonian National Museum of American History\", \"documento\": \"Early ruby laser collection\", \"fato_comprovado\": \"O Smithsonian documenta a realização por Theodore Maiman do primeiro laser de rubi funcional em 1960.\", \"ressalva_ou_pendencia\": \"Não confundir laser de rubi com masers anteriores ou sistemas laser comerciais de outras tecnologias.\", \"url\": \"https://americanhistory.si.edu/collections/object/nmah_712855\", \"limite\": \"Pesquisa de evento e data. Não valida automaticamente impacto ou as 11 notas.\"}, \"convencao_pontuacao_minima_20261105\": {\"nota_minima_operacional\": 1, \"regra\": \"Ausencia de evidencias suficientes para nota maior permite pontuacao minima PROVISORIA, nunca certeza de baixo impacto\", \"precisa_auditoria\": true, \"nao_e_homologacao\": true}}', '[\"Verificar se a ocorrência é um marco tecnológico independente e não apenas fase de uma linhagem já cadastrada.\",\"Conferir os IDs de vínculos antes de concluir que se trata de duplicata.\",\"Revisar as propostas numéricas; lacunas não são notas zero nem um.\",\"Difusão: Obter evidência de adoção efetiva e sua distribuição temporal, não apenas notoriedade histórica.\",\"Magnitude: Quantificar alteração causada pela técnica, evitando inferência baseada na fama do inventor.\",\"Alcance: Determinar alcance geográfico ou setorial com documentos, distinguindo curto e longo prazo.\",\"Persistência: Determinar durabilidade da tecnologia específica e das linhagens derivadas.\",\"Consistência: Confrontar divergências de datas, atribuições e delimitações.\",\"Pervasividade: Demonstrar dependência tecnológica posterior em áreas distintas.\",\"Aprimoramento: Identificar aperfeiçoamentos derivados especificamente do marco.\",\"Complementaridade: Documentar interfaces e integração com outros sistemas tecnológicos.\"]', '[\"MCD-00454\"]', 'Livro p.412; dados de extração e 3/11 propostas; não homologar sem revisão.', '2026-11-04 18:43:55'),
('MCD-00554', 40, 'Introdução comercial do microprocessador Intel 4004', 'CPU de 4 bits em circuito integrado destinada inicialmente a calculadoras.', 1971, NULL, 'Ano do evento por confirmar', 'computação / microprocessadores', 408, 421, 'SEGUNDA_EXTRACAO_EVENTO_COM_RESSALVAS', 'PENDENTE_DE_EVIDENCIAS', 'APROVADO', 0, '{\"o_que_aconteceu\": \"CPU de 4 bits em circuito integrado destinada inicialmente a calculadoras.\", \"transformacao\": \"Criou rota tecnológica para processadores embarcados e microcomputadores.\", \"limitacoes_controversias\": \"Distinguir de transistor e circuito integrado, já catalogados; não atribuir design a só uma pessoa.\", \"origem_da_nova_extracao\": \"Varredura adicional do livro-base (segunda extração). Fonte identificada por página impressa, sem afirmar primazia mundial.\", \"trecho_localizado_livro\": \"in the 1970s and 1980s. Hobbyists began to build personal computers from kits and commercially available microprocessors and floppy disks in the early 1970s. In 1977 college dropouts Steve Jobs and Steve Wozniak brought to market the Apple II, and in 1981 IBM branded the name PC with its own machine powered by the DOS operating \", \"pagina_livro\": 408, \"pagina_pdf\": 421, \"recorte_temporal\": \"ANO DE EVENTO A CONFERIR\", \"validacao\": \"NÃO REVISADO / NÃO HOMOLOGADO\", \"pesquisa_documental_lote4_20261105\": {\"status\": \"CONFERENCIA_DOCUMENTAL_PARCIAL\", \"data_documentada\": \"1971\", \"instituicao\": \"Intel\", \"documento\": \"History of the Intel 4004\", \"fato_comprovado\": \"A Intel identifica 1971 como ano de introdução de seu microprocessador 4004 de quatro bits.\", \"ressalva_ou_pendencia\": \"A expressão primeiro microprocessador comercial depende da definição; distinguir dispositivos experimentais e processadores de múltiplos chips.\", \"url\": \"https://www.intel.com/content/www/us/en/history/virtual-vault/articles/the-intel-4004.html\", \"limite\": \"Pesquisa de evento e data. Não valida automaticamente impacto ou as 11 notas.\"}, \"convencao_pontuacao_minima_20261105\": {\"nota_minima_operacional\": 1, \"regra\": \"Ausencia de evidencias suficientes para nota maior permite pontuacao minima PROVISORIA, nunca certeza de baixo impacto\", \"precisa_auditoria\": true, \"nao_e_homologacao\": true}}', '[\"Verificar se a ocorrência é um marco tecnológico independente e não apenas fase de uma linhagem já cadastrada.\",\"Conferir os IDs de vínculos antes de concluir que se trata de duplicata.\",\"Revisar as propostas numéricas; lacunas não são notas zero nem um.\",\"Difusão: Obter evidência de adoção efetiva e sua distribuição temporal, não apenas notoriedade histórica.\",\"Magnitude: Quantificar alteração causada pela técnica, evitando inferência baseada na fama do inventor.\",\"Alcance: Determinar alcance geográfico ou setorial com documentos, distinguindo curto e longo prazo.\",\"Persistência: Determinar durabilidade da tecnologia específica e das linhagens derivadas.\",\"Pervasividade: Demonstrar dependência tecnológica posterior em áreas distintas.\",\"Complementaridade: Documentar interfaces e integração com outros sistemas tecnológicos.\"]', '[\"MCD-00502\",\"MCD-00422\"]', 'Livro p.408; dados de extração e 5/11 propostas; não homologar sem revisão.', '2026-11-04 18:43:55'),
('MCD-00555', 40, 'Primeiro correio eletrônico entre computadores da ARPANET', 'Programas de mensagens em rede difundiram comunicação assíncrona entre pesquisadores.', 1971, NULL, 'Ano do evento por confirmar', 'redes / comunicação', 409, 422, 'SEGUNDA_EXTRACAO_EVENTO_COM_RESSALVAS', 'PENDENTE_DE_EVIDENCIAS', 'APROVADO', 0, '{\"o_que_aconteceu\": \"Programas de mensagens em rede difundiram comunicação assíncrona entre pesquisadores.\", \"transformacao\": \"Ampliação de usos da rede para comunicação pessoal digital.\", \"limitacoes_controversias\": \"O livro documenta modalidade e-mail, mas não ano; data e precedência exigem revisão especializada.\", \"origem_da_nova_extracao\": \"Varredura adicional do livro-base (segunda extração). Fonte identificada por página impressa, sem afirmar primazia mundial.\", \"trecho_localizado_livro\": \"search labs, and the utility of the network began to demonstrate itself not least in the new modality of e-mail. By the 1990s the Internet (and later the World Wide Web) stood poised for commercial development, and in the last two decades the world has witnessed the development of the incredible and transformative global informa\", \"pagina_livro\": 409, \"pagina_pdf\": 422, \"recorte_temporal\": \"ANO DE EVENTO A CONFERIR\", \"validacao\": \"NÃO REVISADO / NÃO HOMOLOGADO\", \"pesquisa_documental_lote4_20261105\": {\"status\": \"CONFERENCIA_DOCUMENTAL_PARCIAL\", \"data_documentada\": \"1971\", \"instituicao\": \"Lemelson-MIT\", \"documento\": \"Ray Tomlinson\", \"fato_comprovado\": \"O Lemelson-MIT documenta o envio de mensagens eletrônicas entre computadores da ARPANET por Ray Tomlinson em 1971, com uso de @ em endereços.\", \"ressalva_ou_pendencia\": \"Havia correio eletrônico local antes; o marco é o envio de mensagens entre computadores em rede.\", \"url\": \"https://lemelson.mit.edu/resources/ray-tomlinson\", \"limite\": \"Pesquisa de evento e data. Não valida automaticamente impacto ou as 11 notas.\"}, \"convencao_pontuacao_minima_20261105\": {\"nota_minima_operacional\": 1, \"regra\": \"Ausencia de evidencias suficientes para nota maior permite pontuacao minima PROVISORIA, nunca certeza de baixo impacto\", \"precisa_auditoria\": true, \"nao_e_homologacao\": true}}', '[\"Verificar se a ocorrência é um marco tecnológico independente e não apenas fase de uma linhagem já cadastrada.\",\"Conferir os IDs de vínculos antes de concluir que se trata de duplicata.\",\"Revisar as propostas numéricas; lacunas não são notas zero nem um.\",\"Difusão: Obter evidência de adoção efetiva e sua distribuição temporal, não apenas notoriedade histórica.\",\"Magnitude: Quantificar alteração causada pela técnica, evitando inferência baseada na fama do inventor.\",\"Alcance: Determinar alcance geográfico ou setorial com documentos, distinguindo curto e longo prazo.\",\"Persistência: Determinar durabilidade da tecnologia específica e das linhagens derivadas.\",\"Datação: Estabelecer se o ano é o de concepção, construção, patente, difusão ou publicação.\",\"Consistência: Confrontar divergências de datas, atribuições e delimitações.\",\"Pervasividade: Demonstrar dependência tecnológica posterior em áreas distintas.\",\"Aprimoramento: Identificar aperfeiçoamentos derivados especificamente do marco.\",\"Complementaridade: Documentar interfaces e integração com outros sistemas tecnológicos.\"]', '[\"MCD-00428\"]', 'Livro p.409; dados de extração e 2/11 propostas; não homologar sem revisão.', '2026-11-04 18:43:55'),
('MCD-00556', 40, 'Demonstração de telefonia celular portátil Motorola', 'Protótipo de terminal portátil foi demonstrado em sistema experimental celular.', 1973, NULL, 'Ano do evento por confirmar', 'telecomunicações / celular', 411, 424, 'SEGUNDA_EXTRACAO_EVENTO_COM_RESSALVAS', 'PENDENTE_DE_EVIDENCIAS', 'APROVADO', 0, '{\"o_que_aconteceu\": \"Protótipo de terminal portátil foi demonstrado em sistema experimental celular.\", \"transformacao\": \"Antecipou comercialização dos telefones celulares portáteis.\", \"limitacoes_controversias\": \"Não confundir demonstração de 1973 com o aparelho comercializado em 1984.\", \"origem_da_nova_extracao\": \"Varredura adicional do livro-base (segunda extração). Fonte identificada por página impressa, sem afirmar primazia mundial.\", \"trecho_localizado_livro\": \"mpanies such as AT&T—the American Telephone and Telegraph company (“Ma Bell”). The first cell phone, the Motorola Dyna-Tac, dates from 1973. The first trials of a “cell” system that could track and maintain multiple roaming calls took place in Chicago in 1977 with 2,000 customers, and the Japanese built the first commercial cel-\", \"pagina_livro\": 411, \"pagina_pdf\": 424, \"recorte_temporal\": \"ANO DE EVENTO A CONFERIR\", \"validacao\": \"NÃO REVISADO / NÃO HOMOLOGADO\", \"pesquisa_documental_lote4_20261105\": {\"status\": \"CONFERENCIA_DOCUMENTAL_PARCIAL\", \"data_documentada\": \"03/04/1973\", \"instituicao\": \"IEEE Communications Society\", \"documento\": \"Anniversary of the mobile phone\", \"fato_comprovado\": \"A IEEE Communications Society registra o telefonema demonstrativo feito por Martin Cooper com telefone celular portátil em abril de 1973.\", \"ressalva_ou_pendencia\": \"O protótipo da demonstração não era um aparelho comercial amplamente disponível ao público.\", \"url\": \"https://www.comsoc.org/publications/ctn/happy-anniversary-mobile-phone\", \"limite\": \"Pesquisa de evento e data. Não valida automaticamente impacto ou as 11 notas.\"}, \"convencao_pontuacao_minima_20261105\": {\"nota_minima_operacional\": 1, \"regra\": \"Ausencia de evidencias suficientes para nota maior permite pontuacao minima PROVISORIA, nunca certeza de baixo impacto\", \"precisa_auditoria\": true, \"nao_e_homologacao\": true}}', '[\"Verificar se a ocorrência é um marco tecnológico independente e não apenas fase de uma linhagem já cadastrada.\",\"Conferir os IDs de vínculos antes de concluir que se trata de duplicata.\",\"Revisar as propostas numéricas; lacunas não são notas zero nem um.\",\"Difusão: Obter evidência de adoção efetiva e sua distribuição temporal, não apenas notoriedade histórica.\",\"Magnitude: Quantificar alteração causada pela técnica, evitando inferência baseada na fama do inventor.\",\"Alcance: Determinar alcance geográfico ou setorial com documentos, distinguindo curto e longo prazo.\",\"Persistência: Determinar durabilidade da tecnologia específica e das linhagens derivadas.\",\"Consistência: Confrontar divergências de datas, atribuições e delimitações.\",\"Pervasividade: Demonstrar dependência tecnológica posterior em áreas distintas.\",\"Aprimoramento: Identificar aperfeiçoamentos derivados especificamente do marco.\",\"Complementaridade: Documentar interfaces e integração com outros sistemas tecnológicos.\"]', '[\"MCD-00289\"]', 'Livro p.411; dados de extração e 3/11 propostas; não homologar sem revisão.', '2026-11-04 18:43:55');
INSERT INTO `cur_candidatos` (`id_extracao`, `rodada`, `titulo_proposto`, `titulo_original`, `ano_original`, `ano_validado`, `periodo_historico`, `categoria`, `pagina_livro`, `pagina_pdf`, `situacao_identificacao`, `status_avaliacao`, `estado_revisao_humana`, `homologado`, `analise_historica_json`, `pendencias_json`, `duplicatas_json`, `observacao_metodologica`, `criado_em`) VALUES
('MCD-00557', 40, 'Lançamento do computador pessoal IBM PC 5150', 'Computador baseado no Intel 8088 e sistema MS-DOS marcou entrada da IBM no mercado pessoal.', 1981, NULL, 'Ano do evento por confirmar', 'computação / PC', 408, 421, 'SEGUNDA_EXTRACAO_EVENTO_COM_RESSALVAS', 'PENDENTE_DE_EVIDENCIAS', 'APROVADO', 0, '{\"o_que_aconteceu\": \"Computador baseado no Intel 8088 e sistema MS-DOS marcou entrada da IBM no mercado pessoal.\", \"transformacao\": \"Impulsionou ecossistema de hardware e software compatível.\", \"limitacoes_controversias\": \"Não foi o primeiro PC; houve Apple II e outros antes dele.\", \"origem_da_nova_extracao\": \"Varredura adicional do livro-base (segunda extração). Fonte identificada por página impressa, sem afirmar primazia mundial.\", \"trecho_localizado_livro\": \"1970s. In 1977 college dropouts Steve Jobs and Steve Wozniak brought to market the Apple II, and in 1981 IBM branded the name PC with its own machine powered by the DOS operating system licensed from Microsoft Corporation, run by a young Harvard dropout named Bill Gates. Refinements in the field of personal computing included th\", \"pagina_livro\": 408, \"pagina_pdf\": 421, \"recorte_temporal\": \"ANO DE EVENTO A CONFERIR\", \"validacao\": \"NÃO REVISADO / NÃO HOMOLOGADO\", \"pesquisa_documental_lote4_20261105\": {\"status\": \"CONFERENCIA_DOCUMENTAL_PARCIAL\", \"data_documentada\": \"12/08/1981\", \"instituicao\": \"IBM\", \"documento\": \"IBM Personal Computer history\", \"fato_comprovado\": \"A IBM documenta o lançamento do IBM PC modelo 5150 em 12 de agosto de 1981.\", \"ressalva_ou_pendencia\": \"Não foi o primeiro computador pessoal; o marco se refere à plataforma IBM PC e sua difusão/compatibilidade posterior.\", \"url\": \"https://www.ibm.com/history/personal-computer\", \"limite\": \"Pesquisa de evento e data. Não valida automaticamente impacto ou as 11 notas.\"}, \"convencao_pontuacao_minima_20261105\": {\"nota_minima_operacional\": 1, \"regra\": \"Ausencia de evidencias suficientes para nota maior permite pontuacao minima PROVISORIA, nunca certeza de baixo impacto\", \"precisa_auditoria\": true, \"nao_e_homologacao\": true}}', '[\"Verificar se a ocorrência é um marco tecnológico independente e não apenas fase de uma linhagem já cadastrada.\",\"Conferir os IDs de vínculos antes de concluir que se trata de duplicata.\",\"Revisar as propostas numéricas; lacunas não são notas zero nem um.\",\"Difusão: Obter evidência de adoção efetiva e sua distribuição temporal, não apenas notoriedade histórica.\",\"Magnitude: Quantificar alteração causada pela técnica, evitando inferência baseada na fama do inventor.\",\"Alcance: Determinar alcance geográfico ou setorial com documentos, distinguindo curto e longo prazo.\",\"Persistência: Determinar durabilidade da tecnologia específica e das linhagens derivadas.\",\"Pervasividade: Demonstrar dependência tecnológica posterior em áreas distintas.\",\"Complementaridade: Documentar interfaces e integração com outros sistemas tecnológicos.\"]', '[\"MCD-00504\",\"MCD-00426\"]', 'Livro p.408; dados de extração e 5/11 propostas; não homologar sem revisão.', '2026-11-04 18:43:55'),
('MCD-00558', 41, 'Obras de fortificação e muralha da Jericó neolítica', 'Jericó possuía perímetro fortificado e construções permanentes na fase neolítica.', -7350, NULL, 'Referência do período a validar', 'engenharia urbana / construção', 21, 34, 'SEGUNDA_EXTRACAO_CANDIDATO_COM_RESSALVAS', 'PENDENTE_DE_EVIDENCIAS', 'APROVADO', 0, '{\"acontecimento\": \"Jericó possuía perímetro fortificado e construções permanentes na fase neolítica.\", \"possivel_contribuicao\": \"Organização de obras civis para proteção de assentamentos.\", \"restricoes\": \"O livro não demonstra uma data única de invenção de muralhas; recorte é arqueológico e local.\", \"trecho_livro_localizado\": \"al towns had emerged. The classic example is the especially rich Neolithic town of Jericho, which by 7350 bce already had become a well-watered, brick-walled city of 2,000 or more people tending flocks and plots in the surrounding hinterland. Jericho had a tower nine meters high and ten meters in diameter, and its celebrated walls were three meters thick, four meters high, and 700 meters in circumference. The walls were nec- 22 FROM APE TO A\", \"pagina_livro\": 21, \"pagina_pdf_referencia\": 34, \"fonte_externa\": null, \"classificacao\": \"PERIODO_APROXIMADO\", \"autenticacao\": \"PENDENTE\", \"revisao_humana\": \"NAO_REALIZADA\", \"convencao_pontuacao_minima_20261105\": {\"nota_minima_operacional\": 1, \"regra\": \"Ausencia de evidencias suficientes para nota maior permite pontuacao minima PROVISORIA, nunca certeza de baixo impacto\", \"precisa_auditoria\": true, \"nao_e_homologacao\": true}}', '[\"Pesquisar segunda fonte institucional/acadêmica independente e, se possível, documento primário.\",\"Data aproximada/período; não há ano de invenção documentado.\",\"Determinar se o recorte é marco tecnológico independente, ciência fundacional ou contexto histórico.\",\"Conferir as sugestões de sobreposição com os candidatos anteriores.\",\"Todas as notas são propostas documentais; revisão e homologação continuam separadas.\",\"Difusão: Quantificar adoção e escala do recorte histórico, distinguindo o protótipo da difusão posterior.\",\"Magnitude: Estimar a mudança técnica de modo verificável, não inferir magnitude por notoriedade.\",\"Alcance: Obter evidência histórica de abrangência geográfica e de setores afetados.\",\"Persistência: Comprovar duração do uso do mecanismo e distinguir linhagens posteriores.\",\"Independência: Confirmar alegações por pelo menos duas cadeias documentais independentes, não apenas dois sites.\",\"Datação: Validar ano e sua natureza (documento, publicação, invenção, teste, difusão); respeitar incerteza cronológica.\",\"Consistência: Comparar versões documentais e reconciliar divergências de autoria, data ou escopo.\",\"Pervasividade: Documentar derivações concretas em múltiplas áreas.\",\"Aprimoramento: Identificar e datar aperfeiçoamentos diretamente ligados ao marco.\",\"Complementaridade: Demonstrar integração com tecnologias complementares no sistema estudado.\"]', '[\"MCD-00004\"]', 'Base no livro e fonte complementar quando disponível; nenhuma avaliação homologada.', '2026-11-04 20:02:45'),
('MCD-00559', 41, 'Levantamento dos grandes blocos megalíticos de Stonehenge', 'Construção em fases com transporte e posicionamento de blocos de pedra de grande porte.', -2500, NULL, 'Referência do período a validar', 'engenharia de construção / pré-história', 23, 36, 'SEGUNDA_EXTRACAO_CANDIDATO_COM_RESSALVAS', 'PENDENTE_DE_EVIDENCIAS', 'APROVADO', 0, '{\"acontecimento\": \"Construção em fases com transporte e posicionamento de blocos de pedra de grande porte.\", \"possivel_contribuicao\": \"Sistemas de coordenação de mão de obra e técnicas de levantamento.\", \"restricoes\": \"Distinguir fases de 3000 a.C. da elevação das grandes pedras por volta de 2500 a.C.\", \"trecho_livro_localizado\": \"e Bronze Age finally washed across the Salisbury Plain. The word “Stonehenge” means “hanging stone,” and transporting, working, and erecting the huge stones represents a formidable technological achieve- ment on the part of the Neolithic peoples of prehistoric Britain. A huge amount of labor went into building Stonehenge—estimates range to 30 million man-hours, equivalent to an annual productive labor of 10,000 people. In order to create a c\", \"pagina_livro\": 23, \"pagina_pdf_referencia\": 36, \"fonte_externa\": \"https://www.english-heritage.org.uk/visit/places/stonehenge/history-and-stories/timeline\", \"classificacao\": \"PERIODO_APROXIMADO\", \"autenticacao\": \"PENDENTE\", \"revisao_humana\": \"NAO_REALIZADA\", \"convencao_pontuacao_minima_20261105\": {\"nota_minima_operacional\": 1, \"regra\": \"Ausencia de evidencias suficientes para nota maior permite pontuacao minima PROVISORIA, nunca certeza de baixo impacto\", \"precisa_auditoria\": true, \"nao_e_homologacao\": true}}', '[\"Data aproximada/período; não há ano de invenção documentado.\",\"Determinar se o recorte é marco tecnológico independente, ciência fundacional ou contexto histórico.\",\"Conferir as sugestões de sobreposição com os candidatos anteriores.\",\"Todas as notas são propostas documentais; revisão e homologação continuam separadas.\",\"Difusão: Quantificar adoção e escala do recorte histórico, distinguindo o protótipo da difusão posterior.\",\"Magnitude: Estimar a mudança técnica de modo verificável, não inferir magnitude por notoriedade.\",\"Alcance: Obter evidência histórica de abrangência geográfica e de setores afetados.\",\"Persistência: Comprovar duração do uso do mecanismo e distinguir linhagens posteriores.\",\"Independência: Confirmar alegações por pelo menos duas cadeias documentais independentes, não apenas dois sites.\",\"Datação: Validar ano e sua natureza (documento, publicação, invenção, teste, difusão); respeitar incerteza cronológica.\",\"Consistência: Comparar versões documentais e reconciliar divergências de autoria, data ou escopo.\",\"Pervasividade: Documentar derivações concretas em múltiplas áreas.\",\"Aprimoramento: Identificar e datar aperfeiçoamentos diretamente ligados ao marco.\",\"Complementaridade: Demonstrar integração com tecnologias complementares no sistema estudado.\"]', '[\"MCD-00002\"]', 'Base no livro e fonte complementar quando disponível; nenhuma avaliação homologada.', '2026-11-04 20:02:45'),
('MCD-00560', 41, 'Uso administrativo de tabuletas contábeis de Uruk', 'Tabuletas cuneiformes preservadas registravam entradas e saídas econômicas.', -3000, NULL, 'Referência do período a validar', 'gestão / registro escrito', 46, 59, 'SEGUNDA_EXTRACAO_CANDIDATO_COM_RESSALVAS', 'PENDENTE_DE_EVIDENCIAS', 'APROVADO', 0, '{\"acontecimento\": \"Tabuletas cuneiformes preservadas registravam entradas e saídas econômicas.\", \"possivel_contribuicao\": \"Suporte de memória administrativa para tributação e comércio.\", \"restricoes\": \"Sobrepõe-se parcialmente à origem da escrita; delimitar uso documental em vez de contar a escrita duas vezes.\", \"trecho_livro_localizado\": \"nt Mesopotamian invoices—insignia sealed in clay—underscores the economic and utilitarian roots of writing and reckoning. Eighty-five percent of cuneiform tablets uncovered at Uruk (3000 bce), for example, represent economic records, and Egyptian temple and palace records are similar. Ultimately writing came to sup- plant oral traditions and the skills and techniques of human memory. While the vast majority of early written records concern e\", \"pagina_livro\": 46, \"pagina_pdf_referencia\": 59, \"fonte_externa\": null, \"classificacao\": \"PERIODO_APROXIMADO\", \"autenticacao\": \"PENDENTE\", \"revisao_humana\": \"NAO_REALIZADA\", \"convencao_pontuacao_minima_20261105\": {\"nota_minima_operacional\": 1, \"regra\": \"Ausencia de evidencias suficientes para nota maior permite pontuacao minima PROVISORIA, nunca certeza de baixo impacto\", \"precisa_auditoria\": true, \"nao_e_homologacao\": true}}', '[\"Pesquisar segunda fonte institucional/acadêmica independente e, se possível, documento primário.\",\"Data aproximada/período; não há ano de invenção documentado.\",\"Determinar se o recorte é marco tecnológico independente, ciência fundacional ou contexto histórico.\",\"Conferir as sugestões de sobreposição com os candidatos anteriores.\",\"Todas as notas são propostas documentais; revisão e homologação continuam separadas.\",\"Difusão: Quantificar adoção e escala do recorte histórico, distinguindo o protótipo da difusão posterior.\",\"Magnitude: Estimar a mudança técnica de modo verificável, não inferir magnitude por notoriedade.\",\"Alcance: Obter evidência histórica de abrangência geográfica e de setores afetados.\",\"Persistência: Comprovar duração do uso do mecanismo e distinguir linhagens posteriores.\",\"Independência: Confirmar alegações por pelo menos duas cadeias documentais independentes, não apenas dois sites.\",\"Datação: Validar ano e sua natureza (documento, publicação, invenção, teste, difusão); respeitar incerteza cronológica.\",\"Consistência: Comparar versões documentais e reconciliar divergências de autoria, data ou escopo.\",\"Pervasividade: Documentar derivações concretas em múltiplas áreas.\",\"Aprimoramento: Identificar e datar aperfeiçoamentos diretamente ligados ao marco.\",\"Complementaridade: Demonstrar integração com tecnologias complementares no sistema estudado.\"]', '[\"MCD-00471\"]', 'Base no livro e fonte complementar quando disponível; nenhuma avaliação homologada.', '2026-11-04 20:02:45'),
('MCD-00561', 41, 'Compilação dos Elementos de Euclides', 'Euclides sistematizou uma geometria dedutiva na obra Elementos.', -300, NULL, 'Referência do período a validar', 'matemática / fundamentação', 62, 75, 'SEGUNDA_EXTRACAO_CANDIDATO_COM_RESSALVAS', 'PENDENTE_DE_EVIDENCIAS', 'APROVADO', 0, '{\"acontecimento\": \"Euclides sistematizou uma geometria dedutiva na obra Elementos.\", \"possivel_contribuicao\": \"Ferramenta matemática usada por tradições técnicas e científicas posteriores.\", \"restricoes\": \"Obra matemática não implica aplicação tecnológica imediata; avaliar elegibilidade ao Índice Têmporis.\", \"trecho_livro_localizado\": \"rations did not appear full-blown with the Pythagoreans, and the process of developing an axiomatic and deductive plane geometry continued until Euclid compiled his Elements around 300 bce. Nevertheless, to the early Pythagoreans goes the credit for studying mathematics as natural philosophy, for turning Greek mathematics away from practical arithmetic to pure arithmetic and geometry, and for developing the proof as a means and model for jus\", \"pagina_livro\": 62, \"pagina_pdf_referencia\": 75, \"fonte_externa\": null, \"classificacao\": \"PERIODO_APROXIMADO\", \"autenticacao\": \"PENDENTE\", \"revisao_humana\": \"NAO_REALIZADA\", \"convencao_pontuacao_minima_20261105\": {\"nota_minima_operacional\": 1, \"regra\": \"Ausencia de evidencias suficientes para nota maior permite pontuacao minima PROVISORIA, nunca certeza de baixo impacto\", \"precisa_auditoria\": true, \"nao_e_homologacao\": true}}', '[\"Pesquisar segunda fonte institucional/acadêmica independente e, se possível, documento primário.\",\"Data aproximada/período; não há ano de invenção documentado.\",\"Determinar se o recorte é marco tecnológico independente, ciência fundacional ou contexto histórico.\",\"Conferir as sugestões de sobreposição com os candidatos anteriores.\",\"Todas as notas são propostas documentais; revisão e homologação continuam separadas.\",\"Difusão: Quantificar adoção e escala do recorte histórico, distinguindo o protótipo da difusão posterior.\",\"Magnitude: Estimar a mudança técnica de modo verificável, não inferir magnitude por notoriedade.\",\"Alcance: Obter evidência histórica de abrangência geográfica e de setores afetados.\",\"Persistência: Comprovar duração do uso do mecanismo e distinguir linhagens posteriores.\",\"Independência: Confirmar alegações por pelo menos duas cadeias documentais independentes, não apenas dois sites.\",\"Datação: Validar ano e sua natureza (documento, publicação, invenção, teste, difusão); respeitar incerteza cronológica.\",\"Consistência: Comparar versões documentais e reconciliar divergências de autoria, data ou escopo.\",\"Pervasividade: Documentar derivações concretas em múltiplas áreas.\",\"Aprimoramento: Identificar e datar aperfeiçoamentos diretamente ligados ao marco.\",\"Complementaridade: Demonstrar integração com tecnologias complementares no sistema estudado.\"]', '[\"MCD-00017\"]', 'Base no livro e fonte complementar quando disponível; nenhuma avaliação homologada.', '2026-11-04 20:02:45'),
('MCD-00562', 41, 'Padronização de dimensões para catapultas em Alexandria', 'Experimentação helenística produziu relações matemáticas empíricas para dimensionamento de máquinas de arremesso.', -250, NULL, 'Referência do período a validar', 'engenharia militar / cálculo', 87, 100, 'SEGUNDA_EXTRACAO_CANDIDATO_COM_RESSALVAS', 'PENDENTE_DE_EVIDENCIAS', 'APROVADO', 0, '{\"acontecimento\": \"Experimentação helenística produziu relações matemáticas empíricas para dimensionamento de máquinas de arremesso.\", \"possivel_contribuicao\": \"Melhoria do projeto de armamentos e sua reprodução.\", \"restricoes\": \"Data aproximada; fórmula de engenharia não equivale à invenção da catapulta.\", \"trecho_livro_localizado\": \"wledge. After decades of patient effort and record-keeping the scientist-engineers at Alexan- dria created a practical and mathematically exact “catapult formula” that involved extracting cube roots and that specified the optimal dimensions for any ballistic machine and its projectile. With this for- mula Archimedes himself purportedly built the largest stone-throwing catapult on record. But the formula is simply a rule of thumb expressed in\", \"pagina_livro\": 87, \"pagina_pdf_referencia\": 100, \"fonte_externa\": null, \"classificacao\": \"PERIODO_APROXIMADO\", \"autenticacao\": \"PENDENTE\", \"revisao_humana\": \"NAO_REALIZADA\", \"convencao_pontuacao_minima_20261105\": {\"nota_minima_operacional\": 1, \"regra\": \"Ausencia de evidencias suficientes para nota maior permite pontuacao minima PROVISORIA, nunca certeza de baixo impacto\", \"precisa_auditoria\": true, \"nao_e_homologacao\": true}}', '[\"Pesquisar segunda fonte institucional/acadêmica independente e, se possível, documento primário.\",\"Data aproximada/período; não há ano de invenção documentado.\",\"Determinar se o recorte é marco tecnológico independente, ciência fundacional ou contexto histórico.\",\"Conferir as sugestões de sobreposição com os candidatos anteriores.\",\"Todas as notas são pr