INSERT INTO `cur_candidatos` (`id_extracao`, `rodada`, `titulo_proposto`, `titulo_original`, `ano_original`, `ano_validado`, `periodo_historico`, `categoria`, `pagina_livro`, `pagina_pdf`, `situacao_identificacao`, `status_avaliacao`, `estado_revisao_humana`, `homologado`, `analise_historica_json`, `pendencias_json`, `duplicatas_json`, `observacao_metodologica`, `criado_em`) VALUES
('MCD-00586', 43, 'Experimento prismático de Newton e teoria das cores', 'Newton empregou prismas para investigar a refração e a composição da luz.', 1672, NULL, 'Ano do evento a confirmar', 'óptica / experimentação', 269, 282, 'SEGUNDA_EXTRACAO_CANDIDATO_COM_RESSALVAS', 'PENDENTE_DE_EVIDENCIAS', 'APROVADO', 0, '{\"acontecimento\": \"Newton empregou prismas para investigar a refração e a composição da luz.\", \"possivel_contribuicao\": \"Estudo da óptica com desdobramentos instrumentais.\", \"restricoes\": \"É experimento científico; delimitar data de comunicação e efeitos tecnológicos posteriores.\", \"trecho_livro_localizado\": \" results of experiment. Galileo, as we saw, uti- lized experiments to confirm points already established; Newton used experiment one way in his “crucial experiment” of the 1672 paper and in another way in his “proof by experiment” in his Opticks. Harvey undertook systematic experimentation in his dissections, but only as an old-style Aristotelian concerned with “animality” and not to demon- strate the circulation of the blood. “Thought exper\", \"pagina_livro\": 269, \"pagina_pdf_referencia\": 282, \"fonte_externa\": null, \"classificacao\": \"EVENTO_CANDIDATO\", \"autenticacao\": \"PENDENTE\", \"revisao_humana\": \"NAO_REALIZADA\", \"pesquisa_documental_lote5_20261105\": {\"status\": \"CONFERENCIA_DOCUMENTAL_PARCIAL\", \"instituicao\": \"The Newton Project, University of Oxford\", \"titulo_documental\": \"Newton\'s optical correspondence\", \"data_proposta\": \"1666 (ensaios); 1672 (comunicação científica)\", \"fato_fonte\": \"As experiências de Newton com prismas investigaram a composição da luz branca e foram comunicadas à comunidade científica no século XVII.\", \"ressalva\": \"Os experimentos foram desenvolvidos ao longo de anos; não reduzir toda a óptica newtoniana a um único dia ou experimento.\", \"url\": \"https://newtonproject.ox.ac.uk/view/texts/normalized/NATP00003\", \"limite\": \"A fonte sustenta evento e cronologia; nao gera nota, decisao ou homologacao.\"}, \"convencao_pontuacao_minima_20261105\": {\"nota_minima_operacional\": 1, \"regra\": \"Ausencia de evidencias suficientes para nota maior permite pontuacao minima PROVISORIA, nunca certeza de baixo impacto\", \"precisa_auditoria\": true, \"nao_e_homologacao\": true}}', '[\"Pesquisar segunda fonte institucional/acadêmica independente e, se possível, documento primário.\",\"Determinar se o recorte é marco tecnológico independente, ciência fundacional ou contexto histórico.\",\"Conferir as sugestões de sobreposição com os candidatos anteriores.\",\"Todas as notas são propostas documentais; revisão e homologação continuam separadas.\",\"Difusão: Quantificar adoção e escala do recorte histórico, distinguindo o protótipo da difusão posterior.\",\"Magnitude: Estimar a mudança técnica de modo verificável, não inferir magnitude por notoriedade.\",\"Alcance: Obter evidência histórica de abrangência geográfica e de setores afetados.\",\"Persistência: Comprovar duração do uso do mecanismo e distinguir linhagens posteriores.\",\"Independência: Confirmar alegações por pelo menos duas cadeias documentais independentes, não apenas dois sites.\",\"Datação: Validar ano e sua natureza (documento, publicação, invenção, teste, difusão); respeitar incerteza cronológica.\",\"Consistência: Comparar versões documentais e reconciliar divergências de autoria, data ou escopo.\",\"Pervasividade: Documentar derivações concretas em múltiplas áreas.\",\"Aprimoramento: Identificar e datar aperfeiçoamentos diretamente ligados ao marco.\",\"Complementaridade: Demonstrar integração com tecnologias complementares no sistema estudado.\"]', '[\"MCD-00176\"]', 'Base no livro e fonte complementar quando disponível; nenhuma avaliação homologada.', '2026-11-04 20:02:45'),
('MCD-00587', 43, 'Fundação da Accademia dei Lincei', 'Academia italiana reuniu pesquisadores interessados em investigação da natureza.', 1603, NULL, 'Ano do evento a confirmar', 'instituições / ciência', 226, 239, 'SEGUNDA_EXTRACAO_CANDIDATO_COM_RESSALVAS', 'PENDENTE_DE_EVIDENCIAS', 'APROVADO', 0, '{\"acontecimento\": \"Academia italiana reuniu pesquisadores interessados em investigação da natureza.\", \"possivel_contribuicao\": \"Ambiente de patronato e divulgação da ciência moderna.\", \"restricoes\": \"Distinguir fundação institucional de livros de Galileu publicados depois pela Academia.\", \"trecho_livro_localizado\": \"ion for his learning, and he received patronage offers from numerous courts. The next Renaissance academy to concern itself with science was the Accademia dei Lincei (1603–30). The Accademia dei Lincei (or Acad- emy of the Lynx-Eyed) appeared in Rome in 1603, patronized by Roman aristocrat Federico Cesi. Della Porta was an early member, but after 1610 the Lincei, led by Cesi, shifted to Galileo’s more open approach and program for science. G\", \"pagina_livro\": 226, \"pagina_pdf_referencia\": 239, \"fonte_externa\": null, \"classificacao\": \"EVENTO_CANDIDATO\", \"autenticacao\": \"PENDENTE\", \"revisao_humana\": \"NAO_REALIZADA\", \"pesquisa_documental_lote5_20261105\": {\"status\": \"CONFERENCIA_DOCUMENTAL_PARCIAL\", \"instituicao\": \"Accademia Nazionale dei Lincei\", \"titulo_documental\": \"Storia dei Lincei\", \"data_proposta\": \"1603 (fundação)\", \"fato_fonte\": \"A Accademia dei Lincei foi fundada em Roma em 1603, antecedendo instituições científicas nacionais posteriores.\", \"ressalva\": \"Distinguir a academia original das reorganizações e fases institucionais sucessivas.\", \"url\": \"https://www.lincei.it/en/storia\", \"limite\": \"A fonte sustenta evento e cronologia; nao gera nota, decisao ou homologacao.\"}, \"convencao_pontuacao_minima_20261105\": {\"nota_minima_operacional\": 1, \"regra\": \"Ausencia de evidencias suficientes para nota maior permite pontuacao minima PROVISORIA, nunca certeza de baixo impacto\", \"precisa_auditoria\": true, \"nao_e_homologacao\": true}}', '[\"Pesquisar segunda fonte institucional/acadêmica independente e, se possível, documento primário.\",\"Determinar se o recorte é marco tecnológico independente, ciência fundacional ou contexto histórico.\",\"Conferir as sugestões de sobreposição com os candidatos anteriores.\",\"Todas as notas são propostas documentais; revisão e homologação continuam separadas.\",\"Difusão: Quantificar adoção e escala do recorte histórico, distinguindo o protótipo da difusão posterior.\",\"Magnitude: Estimar a mudança técnica de modo verificável, não inferir magnitude por notoriedade.\",\"Alcance: Obter evidência histórica de abrangência geográfica e de setores afetados.\",\"Persistência: Comprovar duração do uso do mecanismo e distinguir linhagens posteriores.\",\"Independência: Confirmar alegações por pelo menos duas cadeias documentais independentes, não apenas dois sites.\",\"Datação: Validar ano e sua natureza (documento, publicação, invenção, teste, difusão); respeitar incerteza cronológica.\",\"Consistência: Comparar versões documentais e reconciliar divergências de autoria, data ou escopo.\",\"Pervasividade: Documentar derivações concretas em múltiplas áreas.\",\"Aprimoramento: Identificar e datar aperfeiçoamentos diretamente ligados ao marco.\",\"Complementaridade: Demonstrar integração com tecnologias complementares no sistema estudado.\"]', '[\"MCD-00123\"]', 'Base no livro e fonte complementar quando disponível; nenhuma avaliação homologada.', '2026-11-04 20:02:45'),
('MCD-00588', 44, 'Aprimoramento da fiação com cardagem cilíndrica', 'Mecanização da preparação de fibras pela cardagem cilíndrica.', 1775, NULL, 'Ano do evento a confirmar', 'indústria têxtil / cardagem', 285, 298, 'SEGUNDA_EXTRACAO_CANDIDATO_COM_RESSALVAS', 'PENDENTE_DE_EVIDENCIAS', 'APROVADO', 0, '{\"acontecimento\": \"Mecanização da preparação de fibras pela cardagem cilíndrica.\", \"possivel_contribuicao\": \"Contribuição à produtividade e ao equilíbrio da cadeia têxtil.\", \"restricoes\": \"Não equivale à invenção da lançadeira volante nem do tear mecânico.\", \"trecho_livro_localizado\": \"ed spinning; these improvements left weaving as the constriction point in the pro- duction process, an imbalance intensified by the invention of cylinder carding in 1775 which made spinning even more efficient. After 1785, with the mechanically powered loom, to which the steam engine would ultimately be applied as an independent power source, weaving be- came mechanized. Not unexpectedly, therefore, between 1764 and 1812 worker productivity \", \"pagina_livro\": 285, \"pagina_pdf_referencia\": 298, \"fonte_externa\": null, \"classificacao\": \"EVENTO_CANDIDATO\", \"autenticacao\": \"PENDENTE\", \"revisao_humana\": \"NAO_REALIZADA\", \"convencao_pontuacao_minima_20261105\": {\"nota_minima_operacional\": 1, \"regra\": \"Ausencia de evidencias suficientes para nota maior permite pontuacao minima PROVISORIA, nunca certeza de baixo impacto\", \"precisa_auditoria\": true, \"nao_e_homologacao\": true}}', '[\"Pesquisar segunda fonte institucional/acadêmica independente e, se possível, documento primário.\",\"Determinar se o recorte é marco tecnológico independente, ciência fundacional ou contexto histórico.\",\"Conferir as sugestões de sobreposição com os candidatos anteriores.\",\"Todas as notas são propostas documentais; revisão e homologação continuam separadas.\",\"Difusão: Quantificar adoção e escala do recorte histórico, distinguindo o protótipo da difusão posterior.\",\"Magn