('MCD-00109', 'impacto_difusao', 1, 'AVALIADO', 'Cópias circularam em pequenos círculos astronômicos, sem ampla difusão pública inicial', '{\"documento_base\":\"McClellan III e Dorn (2006), p. 209\",\"inferencia_a_auditar\":\"Cópias circularam em pequenos círculos astronômicos, sem ampla difusão pública inicial\",\"limite_historico\":\"O inventário de 1514 comprova a existência da cópia, não que o manuscrito tenha sido escrito ou divulgado após essa data.\",\"fontes_consulta\":[\"B2006\",\"GAL\",\"CAM\"]}', '[\"B2006\",\"GAL\",\"CAM\"]', NULL),
('MCD-00109', 'impacto_magnitude', 3, 'AVALIADO', 'Formulação heliocêntrica transformou programa conceitual de estudo planetário', '{\"documento_base\":\"McClellan III e Dorn (2006), p. 209\",\"inferencia_a_auditar\":\"Formulação heliocêntrica transformou programa conceitual de estudo planetário\",\"limite_historico\":\"O inventário de 1514 comprova a existência da cópia, não que o manuscrito tenha sido escrito ou divulgado após essa data.\",\"fontes_consulta\":[\"B2006\",\"GAL\",\"CAM\"]}', '[\"B2006\",\"GAL\",\"CAM\"]', NULL),
