('MCD-00289', 'fund_pervasividade', 3, 'AVALIADO', 'Pervasividade preliminar: Telecomunicações, comércio, segurança e serviços públicos. São setores relacionados, não estimativa de proporção mundial.', '{\"documento_base\":\"McClellan III e Dorn, 2006, p. 319\",\"inferencia_a_auditar\":\"Pervasividade preliminar: Telecomunicações, comércio, segurança e serviços públicos. São setores relacionados, não estimativa de proporção mundial.\",\"limites\":\"O original inclui eventos de 1878, 1884 e 1915; escolha específica de 1878 impede misturar várias datas.\",\"url_referencia_externa\":\"https://home.nps.gov/subjects/nationalhistoriclandmarks/site-of-the-first-telephone-exchange.htm\",\"natureza\":\"PONTUACAO_PRELIMINAR_SUJEITA_A_AUDITORIA\"}', '[\"B2006\",\"EXT1\"]', NULL),
('MCD-00289', 'impacto_alcance', 3, 'AVALIADO', 'Alcance preliminar: Comunicações comerciais, serviços e residências. Não extrapolar cobertura geográfica sem dados.', '{\"documento_base\":\"McClellan III e Dorn, 2006, p. 319\",\"inferencia_a_auditar\":\"Alcance preliminar: Comunicações comerciais, serviços e residências. Não extrapolar cobertura geográfica sem dados.\",\"limites\":\"O original inclui eventos de 1878, 1884 e 1915; escolha específica de 1878 impede misturar várias datas.\",\"url_referencia_externa\":\"https://home.nps.gov/subjects/nationalhistoriclandmarks/site-of-the-first-telephone-exchange.htm\",\"natureza\":\"PONTUACAO_PRELIMINAR_SUJEITA_A_AUDITORIA\"}', '[\"B2006\",\"EXT1\"]', NULL),
