INSERT INTO `cur_criterios` (`id_extracao`, `codigo`, `nota`, `situacao`, `justificativa`, `evidencias_json`, `fontes_ids_json`, `o_que_falta`) VALUES
('MCD-00454', 'impacto_persistencia', 1, 'AVALIADO', 'SEM_EVIDENCIA: ainda não há suporte suficiente para classificar duração de emprego do método e descendentes técnicos deste acontecimento de modo individualizado. A elegibilidade está suspensa por contexto/duplicidade e não deve ser inferida a partir da importância do processo geral. Ação: delimitar o marco, localizar referência independente e comparar alternativas; ressalva: Não confundir adaptação e aplicação astronômica com invenção holandesa de 1608; possível sobreposição com MCD-00170. [MAT-POLITICA-NOTA1-20261105] Nota 1 atribuida pela convencao conservadora de pontuacao minima quando inexistente evidência para justificar grau maior. Ausencia de evidencias NAO significa demonstracao de baixo impacto; a incerteza permanece registrada para auditoria.', '{\"documento_base\": \"McClellan III e Dorn, 2006, p. 431\", \"memoria_calculo\": \"SEM_EVIDENCIA: ainda não há suporte suficiente para classificar duração de emprego do método e descendentes técnicos deste acontecimento de modo individualizado. A elegibilidade está suspensa por contexto/duplicidade e não deve ser inferida a partir da importância do processo geral. Ação: delimitar o marco, localizar referência independente e comparar alternativas; ressalva: Não confundir adaptação e aplicação astronômica com invenção holandesa de 1608; possível sobreposição com MCD-00170.\", \"natureza\": \"AVALIACAO_PROVISORIA_SEM_HOMOLOGACAO\", \"ressalva\": \"Não confundir adaptação e aplicação astronômica com invenção holandesa de 1608; possível sobreposição com MCD-00170.\", \"fonte_externa\": \"https://brunelleschi.imss.fi.it/esplora/cannocchiale/dswmedia/storia/estoria1_st.html\", \"escopo\": \"D\", \"politica_nota1_20261105\": {\"nota_anterior\": null, \"situacao_anterior\": \"SEM_EVIDENCIA\", \"nota_atribuida\": 1, \"motivo\": \"NOTA_NULA\", \"base_da_nota\": \"REGRA_CONSERVADORA_SEM_EVIDENCIA_ESPECIFICA\", \"validacao_cientifica\": false, \"alerta\": \"1 nao prova impacto baixo\"}}', '[\"B2006\",\"EXT1\"]', 'Falta fundamentação específica para impacto_persistencia, ou verificar escopo/duplicidade.'),
('MCD-00455', 'conf_consistencia', 1, 'AVALIADO', 'SEM_EVIDENCIA em consistência: trecho descreve contexto, tendência, interpretação, estatística ou período amplo, não uma inovação única comparável ao corpus. McClellan III e Dorn (2006), p. impressa 434, p. PDF 447. Investigar delimitação antes de avaliar. [MAT-POLITICA-NOTA1-20261105] Nota 1 atribuida pela convencao conservadora de pontuacao minima quando inexistente evidência para justificar grau maior. Ausencia de evidencias NAO significa demonstracao de baixo impacto; a incerteza permanece registrada para auditoria.', '{\"ano_importado\": 1960, \"ano_revisado\": null, \"tipo_triagem\": \"C\", \"pagina_livro\": 434, \"fontes_efetivas\": [\"B2006\"], \"status_cientifico\": \"PROPOSTA_NAO_HOMOLOGADA\", \"politica_nota1_20261105\": {\"nota_anterior\": null, \"situacao_anterior\": \"SEM_EVIDENCIA\", \"nota_atribuida\": 1, \"motivo\": \"NOTA_NULA\", \"base_da_nota\": \"REGRA_CONSERVADORA_SEM_EVIDENCIA_ESPECIFICA\", \"validacao_cientifica\": false, \"alerta\": \"1 nao prova impacto baixo\"}}', '[\"B2006\"]', 'Falta evento singular e/ou fonte independente com evidência específica para essa dimensão.'),
